/// IC IALLUIS (IC IALLUIS)
fn a294(c: &mut dyn Context, m: u64) -> Result<Effect, Effect> {
    let _ = m;
    if (at_el0_in_host(c)) || (at_el0_not_in_host(c)) {
        return Ok(Effect::Undefined);
    }
    if (c.el()) == (1) {
        if !(can_trap_ic(
            c,
            CacheType::Instruction,
            CacheOp::Invalidate,
            CacheScope::PoU,
        )) {
            return Ok(Effect::Done);
        }
        if ((bits(c.read(Register::HCR_EL2, 0), 24, 1)) & 0x1) == 0x1 {
            return Ok(Effect::Trap {
                el: 2 as u8,
                ec: 24u64,
            });
        }
        if ((bits(c.read(Register::HCR_EL2, 0), 50, 1)) & 0x1) == 0x1 {
            return Ok(Effect::Trap {
                el: 2 as u8,
                ec: 24u64,
            });
        }
        if ((bits(c.read(Register::HFGITR_EL2, 0), 0, 1)) & 0x1) == 0x1 {
            return Ok(Effect::Trap {
                el: 2 as u8,
                ec: 24u64,
            });
        }
        if treat_ic_as_nop(
            c,
            CacheType::Instruction,
            CacheOp::Invalidate,
            CacheScope::PoU,
        ) {
            return Ok(Effect::Done);
        }
        {
            let operation = Operation::Ic {
                scope: CacheScope::ALLUIS,
                operand: 0,
            };
            c.operation(operation)?;
        }
        return Ok(Effect::Done);
    }
    if (c.el()) == (2) {
        if !(can_trap_ic(
            c,
            CacheType::Instruction,
            CacheOp::Invalidate,
            CacheScope::PoU,
        )) {
            return Ok(Effect::Done);
        }
        if treat_ic_as_nop(
            c,
            CacheType::Instruction,
            CacheOp::Invalidate,
            CacheScope::PoU,
        ) {
            return Ok(Effect::Done);
        }
        {
            let operation = Operation::Ic {
                scope: CacheScope::ALLUIS,
                operand: 0,
            };
            c.operation(operation)?;
        }
        return Ok(Effect::Done);
    }
    Ok(Effect::Refused("no AARCHMRS case applies"))
}

